/// <summary>
///     Constructs a <c>METItemPackChangeCompletedBusinessEventContract</c>.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_tempItemPackChg">List of Temp Item Pack Change</param>
/// <param name = "_sites">List of Sites</param>
/// <returns>An instance of <c>METItemPackChangeCompletedBusinessEventContract</c>.</returns>
public static METItemPackChangeCompletedBusinessEventContract newFromItemPackChangeCompleted(ItemId _itemId, METTempItemPackChg _tempItemPackChg, list _inventSiteId)
{
    METItemPackChangeCompletedBusinessEventContract contract = new METItemPackChangeCompletedBusinessEventContract();
    contract.initialize(_itemId, _tempItemPackChg, _inventSiteId);
    return contract;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>Item Id</returns>
[DataMember('Item'), BusinessEventsDataMember("@SYS123828")]
public ItemId parmItemId(itemId _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_tempItemPackChg">List of Temp Item Pack Change</param>
/// <returns>List of Temp Item Pack Change</returns>
[DataMember('TempItemForPackChange'), BusinessEventsDataMember("@MET:TemporaryItemForPackChange")]
public METTempItemPackChg parmtempItemPackChg( METTempItemPackChg _tempItemPackChg = tempItemPackChg)
{
    tempItemPackChg = _tempItemPackChg;

    return tempItemPackChg;
}

/// <summary>
/// List of Sites
/// </summary>
/// <param name = "_inventSiteId">List of Sites</param>
/// <returns>List of sites</returns>
[
 DataMember('Site'), 
 DataCollection(Types::String),
 BusinessEventsDataMember("@SYS103211")]
public List parmInventSiteId(List _inventSiteId = inventSiteId)
{
    inventSiteId = _inventSiteId;

    return inventSiteId;
}

/// <summary>
/// Initializes the data members
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_tempItemPackChg">Temp item pack change</param>
/// <param name = "_inventSiteId">Invent Site Id</param>
private void initialize(ItemId _itemId, METTempItemPackChg _tempItemPackChg, list _inventSiteId)
{
    tempItemPackChg = _tempItemPackChg;
    itemId = _itemId;
    inventSiteId = _inventSiteId;
}
